"""Generated by make contracts from packages/contracts/events. Do not edit."""

from __future__ import annotations

from enum import StrEnum
from typing import Annotated
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field


class Reason(StrEnum):
    """
    Why: not_a_rule, the document states no rule; wrong_extraction, the model read it wrongly; duplicate, another candidate or rule already holds it; out_of_scope, a rule the product does not cover; unparseable, the extraction gave no candidate to draft from.
    """

    not_a_rule = "not_a_rule"
    wrong_extraction = "wrong_extraction"
    duplicate = "duplicate"
    out_of_scope = "out_of_scope"
    unparseable = "unparseable"


class RuleRejectedV1(BaseModel):
    """
    An analyst rejected a rule candidate the pipeline extracted: before drafting it, or after drafting it into a rule version that their review then refused. No rule changes: the candidate is closed with the reason, and a draft made from it stays a draft. Producer: rulebook (the decision on a candidate's review task, in the same transaction). Consumers: none yet; the pipeline's operations and the golden export read rejections later.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    candidate_id: Annotated[
        UUID,
        Field(description="The rejected candidate, as rule.candidate.created named it."),
    ]
    document_id: Annotated[UUID, Field(description="The document it was extracted from.")]
    regulator: Annotated[
        str,
        Field(
            description="The regulator of the candidate's review queue, in lower case.",
            min_length=1,
        ),
    ]
    reason: Annotated[
        Reason,
        Field(
            description="Why: not_a_rule, the document states no rule; wrong_extraction, the model read it wrongly; duplicate, another candidate or rule already holds it; out_of_scope, a rule the product does not cover; unparseable, the extraction gave no candidate to draft from."
        ),
    ]
    prompt_version: Annotated[
        str,
        Field(
            description="The prompt the candidate was extracted with, as name@version.",
            min_length=1,
        ),
    ]
    model: Annotated[str, Field(description="The model that produced the candidate.", min_length=1)]
    rule_version_id: Annotated[
        UUID | None,
        Field(
            description="The draft the candidate became, when it was drafted before the rejection; null when it was rejected before drafting."
        ),
    ]
